class ChromaLibrarianClient:
    """Persistent ChromaDB client with SHA-256 idempotency."""
    def upsert_chunk(self, chunk: SummarizedChunk, meta: dict) -> UpsertResult:
        existing = self._collection.get(ids=[meta['content_hash']])
        if existing['ids'] and existing['metadatas'][0]['file_path'] == meta['file_path']:
            return UpsertResult(action='skipped', id=meta['content_hash'])
        if existing['ids']:
            self._collection.update(ids=[meta['content_hash']], metadatas=[meta])
            return UpsertResult(action='metadata_updated', id=meta['content_hash'])
        self._collection.add(ids=[meta['content_hash']], documents=[chunk.content], metadatas=[meta])
        return UpsertResult(action='inserted', id=meta['content_hash'])

@app.on_event('startup')
async def warmup_models():
    """Pre-warm Ollama model on server start to avoid cold-start latency on first request."""
    try:
        async with httpx.AsyncClient() as client:
            await client.post(
                f'{settings.OLLAMA_HOST}/api/generate',
                json={'model': settings.OLLAMA_MODEL, 'prompt': 'warmup', 'stream': False},
                timeout=120.0,
            )
        logger.info('Model warmup complete')
    except Exception as exc:
        logger.warning('Model warmup failed (non-fatal): %s', exc)

class DeveloperMemoryWatchdog(FileSystemEventHandler):
    """Trigger incremental sync on file changes within a watched repository."""
    def __init__(self, sync_fn: Callable[[str, str], None], debounce_secs: float = 2.0):
        self._sync_fn = sync_fn
        self._debounce = debounce_secs
        self._last_event: dict[str, float] = {}

    def on_modified(self, event: FileModifiedEvent) -> None:
        if event.is_directory:
            return
        now = time.time()
        if now - self._last_event.get(event.src_path, 0) < self._debounce:
            return
        self._last_event[event.src_path] = now
        self._sync_fn(event.src_path, 'main')
